// CS PDCA credential edit -> a flat {ws, bison_key, aimfox_key} payload.
//
// Column semantics (docs/reference/n8n/aimfox-phase-a.md, ops/sheets-bison-credential-sync):
//   E  = col_5   Bison workspace id  -- the ONLY client identity this payload carries
//   F  = col_6   Bison API key
//   DA = col_105 Aimfox token
//
// Keys never leave n8n: this payload goes straight into the Postgres node next to it and nothing
// here is logged. The Apps Script sends one request per edited sheet row and always sends all
// three values, so re-syncing every column on every edit is self-healing rather than dependent on
// which cell happened to be touched.
const out = [];

for (const item of $input.all()) {
  const body = item.json?.body ?? {};

  if (body.event !== 'pdca_credentials_updated') {
    throw new Error(`Unexpected event "${body.event}" - refusing to touch credentials.`);
  }
  if (body.sheetName !== 'CS PDCA') {
    throw new Error(`Unexpected sheet "${body.sheetName}" - refusing to touch credentials.`);
  }

  const byColumn = Object.fromEntries((body.fields ?? []).map((f) => [f.column, f.value]));
  const pick = (column) => String(body.values?.[column] ?? byColumn[column] ?? '').trim();

  const ws = pick('E');
  const sheetRow = body.row ?? null;

  // No workspace id -> no way to resolve the client. Report it, never guess.
  if (!/^\d+$/.test(ws)) {
    out.push({ json: { sheet_row: sheetRow, skipped: 'no-workspace-id', aimfox_key: null, payload: '[]' } });
    continue;
  }

  const aimfoxKey = pick('DA') || null;

  out.push({
    json: {
      sheet_row: sheetRow,
      edited_columns: (body.editedColumns ?? []).join(','),
      // Surfaced for the Authorization header of "[AF] Resolve workspace" only. It stays inside
      // n8n exactly as the payload does, and nothing downstream logs either.
      aimfox_key: aimfoxKey,
      payload: JSON.stringify([
        { ws, bison_key: pick('F') || null, aimfox_key: aimfoxKey },
      ]),
    },
  });
}

return out;
